from typing import List, Tuple

def f(n: int, m: int, k: int, coordinates: List[Tuple[int, int]]):
    # Initialization
    grid = [[0] * m for _ in range(n)]
    for x, y in coordinates:
        grid[x][y] = 1

    for x in range(n):
        for y in range(m):
            if grid[x][y] == 1:
                grid[x][y] = -1

    result = 0
    for x in range(n):
        for y in range(m):
            if grid[x][y] == 1:
                count = 1
                x1, y1 = x, y
                while True:
                    grid[x1][y1] = -1
                    if x1 > 0 and grid[x1-1][y1] == 1:
                        x1 -= 1
                        count += 1
                    elif x1 < n-1 and grid[x1+1][y1] == 1:
                        x1 += 1
                        count += 1
                    elif y1 > 0 and grid[x1][y1-1] == 1:
                        y1 -= 1
                        count += 1
                    elif y1 < m-1 and grid[x1][y1+1] == 1:
                        y1 += 1
                        count += 1
                    else:
                        break
                result += count

    return -1 if any(x == 0 or y == 0 or x == n-1 or y == m-1 for x, y in coordinates) else result
```

